const august11ResearchPosts: ReadonlyArray<ResearchPost> = [
  { slug:'outsourced-programmer-mean-time-to-review-study', title:'Mean time to review in outsourced programming teams', excerpt:'A measurement study for separating review delay from implementation time in distributed software delivery.', topic:'Review latency', published:'2026-08-12', body:[
    'Review delay and coding time are different operational signals. A pull request can be technically complete while waiting for a reviewer, so combining both intervals hides where work is actually stalled.',
    'DORA treats software delivery performance as a system outcome rather than an individual productivity score. GitHub records review requests, comments, approvals, and merge events, which gives teams a reproducible event trail for measuring review flow.',
    'A useful baseline records the median and upper-quartile time from review request to first substantive review. Draft time, weekends, automated bot comments, and author self-reviews should be classified consistently before comparisons are made.',
    'The evidence should also distinguish queue delay from review duration. Queue delay ends when a qualified reviewer begins; review duration covers the period until approval or a clear request for changes.',
    'The strongest interpretation is comparative, not universal. Track the same repository and ticket classes over time, then examine whether reviewer coverage, pull-request size, or unclear ownership explains changes.',
    'Research takeaway: measure the review system and its queues, not developer presence, and retain merge authority with the company technical owner.'
  ], sources:[['DORA research program','https://dora.dev/research/'],['GitHub pull request review documentation','https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/reviewing-changes-in-pull-requests/about-pull-request-reviews']] },
  { slug:'remote-developer-pull-request-size-analysis', title:'Pull request size and reviewability for remote developers', excerpt:'An evidence-led analysis of change size, reviewer load, and risk in distributed code review.', topic:'Pull request size', published:'2026-08-12', body:[
    'Pull-request size is observable, but raw line count is not a complete measure of difficulty. Generated files, dependency locks, renames, tests, and behavioral code create different review burdens even when their totals match.',
    'Google engineering guidance recommends small, self-contained changes because they are easier to review correctly and faster to move through the system. GitHub review controls provide the approval and discussion record needed to test that relationship in a specific repository.',
    'A defensible analysis groups changes by work type and records changed files, non-generated lines, review rounds, elapsed review time, reopened work, and post-merge defects. It excludes mechanical output or reports it separately.',
    'Teams should compare distributions rather than choose a universal maximum. If larger behavioral changes repeatedly produce longer queues or more rework, the evidence supports narrower implementation slices for that codebase.',
    'Small changes are not automatically safe. A short authorization edit may carry more risk than a large test-fixture update, so security and release ownership remain independent controls.',
    'Research takeaway: use size as a review-planning signal alongside change type and risk, never as a developer performance quota.'
  ], sources:[['Google Engineering Practices: small changes','https://google.github.io/eng-practices/review/developer/small-cls.html'],['GitHub pull request review documentation','https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/reviewing-changes-in-pull-requests/about-pull-request-reviews']] },
  { slug:'outsourced-software-defect-escape-rate-study', title:'Studying defect escape rates in outsourced software work', excerpt:'A source-led method for learning from defects found after an agreed validation boundary.', topic:'Defect escape rate', published:'2026-08-12', body:[
    'A defect escape rate is meaningful only after the team defines the boundary that a defect escaped. Discovery after developer checks, after staging acceptance, and after production release represent different control failures.',
    'ISO software-testing guidance emphasizes planned test processes and documented evidence, while the NIST Secure Software Development Framework connects verification practices to software risk. These sources support a traceable classification rather than a blame metric.',
    'A study should record the affected release, severity, discovery stage, originating change, expected test, actual evidence, and whether the requirement was known. Duplicate reports and unrelated operational incidents should be removed from the numerator.',
    'Compare rates within similar release classes and include the size of the opportunity set, such as accepted changes or releases. A percentage without its denominator or severity mix can create a misleading trend.',
    'The useful output is a control decision: add a missing case, clarify acceptance evidence, improve a fixture, or change review ownership. Ranking individual remote developers from sparse defect counts is not supported by this method.',
    'Research takeaway: escaped defects should improve the validation system while final acceptance and release decisions remain with the company.'
  ], sources:[['ISO/IEC/IEEE 29119 software testing overview','https://www.iso.org/standard/45142.html'],['NIST Secure Software Development Framework','https://csrc.nist.gov/Projects/ssdf']] },
  { slug:'distributed-engineering-handoff-latency-research', title:'Handoff latency in distributed engineering teams', excerpt:'Research on the time between a completed work state and the next owner taking accountable action.', topic:'Handoff latency', published:'2026-08-12', body:[
    'Distributed work creates handoffs across authors, reviewers, QA owners, and release owners. The relevant delay begins when a work item has the evidence required for the next decision, not when someone posts a generic status update.',
    'DORA research frames delivery as a flow system, and Google technical-writing guidance supports documentation that lets another person act accurately. Together they point to observable handoff states and usable records.',
    'Measure the interval from a declared ready state to the next accountable action. The record should identify the ticket, commit or artifact, checks performed, open risks, requested decision, and named next owner.',
    'Separate incomplete handoffs from queue delay. If required evidence is absent, the item was not ready; if the package is complete but untouched, reviewer capacity or ownership is the stronger explanation.',
    'Median time, upper-quartile time, and the share of handoffs returned for missing context provide a more complete view than average response time alone.',
    'Research takeaway: reduce ambiguity at ownership boundaries and measure decision flow, not online activity or message volume.'
  ], sources:[['DORA research program','https://dora.dev/research/'],['Google Technical Writing courses','https://developers.google.com/tech-writing']] },
  { slug:'outsourced-programmer-access-review-frequency-study', title:'Access review frequency for outsourced programmers', excerpt:'An evidence-based framework for choosing event-driven and periodic access reviews.', topic:'Access governance', published:'2026-08-12', body:[
    'Access-review frequency should reflect account risk, work duration, privilege, and change events. A single calendar interval cannot represent a short low-risk ticket and an administrator role with production access equally well.',
    'NIST access-control guidance addresses account management and periodic review, while CISA Secure by Design emphasizes reducing avoidable exposure. The evidence supports both scheduled review and immediate event-driven review.',
    'Trigger a review when a project ends, responsibilities change, elevated access expires, an account becomes inactive, or an incident affects identity controls. Periodic checks then catch drift not covered by those events.',
    'A review record should connect each named account to an active owner, approved purpose, privilege level, last use, authentication controls, and removal decision. Shared credentials weaken that evidence and should not be treated as equivalent.',
    'Measure orphaned accounts, overdue removals, unjustified elevated roles, and time from offboarding event to access removal. Do not use login frequency as a proxy for contribution.',
    'Research takeaway: combine risk-based periodic reviews with immediate lifecycle events and keep approval for privileged access inside the company.'
  ], sources:[['NIST SP 800-53 Rev. 5 access control','https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final'],['CISA Secure by Design','https://www.cisa.gov/securebydesign']] },
  { slug:'remote-development-test-flake-rate-analysis', title:'Analyzing flaky tests in remote development workflows', excerpt:'A reproducible method for separating nondeterministic tests from product regressions and environment failures.', topic:'Test reliability', published:'2026-08-12', body:[
    'A flaky test produces inconsistent outcomes without a relevant product change, but rerunning every failure until it passes can conceal real regressions. Classification requires the same revision, controlled inputs, and recorded environment.',
    'Google Testing guidance documents the operational cost of test flakiness, while OpenTelemetry provides conventions for traces and signals that can help correlate failures with environment or dependency behavior.',
    'An analysis should retain the test identifier, commit, runner image, dependency state, seed, failure signature, retry result, and known infrastructure incident. Intentional quarantine must remain visible rather than silently removing evidence.',
    'Report the share of test executions and the share of unique tests affected. A small number of frequently executed flaky tests can distort execution-level rates, while a broad set of rare failures indicates a different problem.',
    'Prioritize by blocked developer time, release impact, and diagnostic confidence. Ownership should follow the failing system or fixture, not automatically the remote programmer who encountered it.',
    'Research takeaway: treat flakiness as a reliability defect with reproducible evidence, not as permission to ignore failed checks.'
  ], sources:[['Google Testing Blog: flaky tests','https://testing.googleblog.com/2016/05/flaky-tests-at-google-and-how-we.html'],['OpenTelemetry documentation','https://opentelemetry.io/docs/']] },
  { slug:'outsourced-code-review-rework-rate-study', title:'Rework rates after outsourced code review', excerpt:'Research on measuring substantive review changes without rewarding superficial approvals.', topic:'Review rework', published:'2026-08-12', body:[
    'Review rework is the change made in response to a substantive finding before merge. Comment count alone is unsuitable because questions, automated notices, formatting notes, and risk findings have different meaning.',
    'GitHub preserves review states and discussions, while Microsoft Security Development Lifecycle practices support risk-based review for security-relevant changes. These records allow review outcomes to be classified by purpose.',
    'A study can group requested changes into correctness, security, test evidence, maintainability, requirements, and style. It should record whether the change altered behavior, added missing proof, or only clarified the submission.',
    'High rework may identify unclear requirements, unfamiliar code, or effective detection of risk. Low rework may reflect strong preparation or weak review, so direction alone does not establish quality.',
    'Compare similar work classes and examine downstream defects, reopened changes, and review latency. The goal is to improve briefs and checks, not minimize reviewer intervention at any cost.',
    'Research takeaway: interpret rework with risk and outcome evidence while preserving independent company review before merge.'
  ], sources:[['GitHub pull request review documentation','https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/reviewing-changes-in-pull-requests/about-pull-request-reviews'],['Microsoft Security Development Lifecycle practices','https://www.microsoft.com/en-us/securityengineering/sdl/practices']] },
  { slug:'distributed-developer-onboarding-time-analysis', title:'Analyzing onboarding time for distributed developers', excerpt:'An evidence-led model for measuring readiness milestones instead of chat presence or calendar tenure.', topic:'Developer onboarding', published:'2026-08-12', body:[
    'Onboarding is not one timestamp. Environment setup, repository comprehension, first reviewed change, and independent completion of a bounded task are separate readiness milestones.',
    'Google technical-writing guidance supports instructions tested against user needs, and GitHub review records provide durable evidence for a first accepted change. Together they support milestone-based analysis.',
    'Record when access was approved, setup was reproducibly completed, the first test passed, the first pull request entered review, and the first bounded change was accepted. Note delays controlled by the company, such as missing permissions or reviewer availability.',
    'Compare similar roles and repositories rather than setting one universal target. Legacy systems, regulated access, and unfamiliar build environments legitimately produce different paths.',
    'Useful outcomes include setup-guide defects found, blocked hours by cause, review rounds on the first change, and time to repeat a task with less assistance. Message volume and online time do not establish readiness.',
    'Research takeaway: evaluate the onboarding system through observable milestones and remove company-controlled blockers before judging contributor progress.'
  ], sources:[['Google Technical Writing courses','https://developers.google.com/tech-writing'],['GitHub pull request review documentation','https://docs.github.com/en/pull-requests/collaborating-with-pull-requests/reviewing-changes-in-pull-requests/about-pull-request-reviews']] },
  { slug:'outsourced-release-rollback-readiness-study', title:'Rollback readiness for outsourced software releases', excerpt:'A source-led study of whether a release can be reversed and verified without transferring release authority.', topic:'Rollback readiness', published:'2026-08-12', body:[
    'A rollback plan is evidence only when the team can identify the release unit, prior known-good state, triggering conditions, operator, data implications, and post-rollback checks. A generic statement that changes are reversible is insufficient.',
    'DORA research connects delivery performance with reliable practices, and the NIST Secure Software Development Framework calls for protected releases and response planning. Both support testing recovery before an incident.',
    'Review a representative sample of releases for artifact immutability, configuration compatibility, database reversibility, feature-flag behavior, monitoring, and owner-approved commands. Data migrations may require forward recovery rather than a simple code rollback.',
    'Measure plans tested, time to reach the prior service state, failed verification checks, and exceptions without an approved recovery path. Distinguish rehearsal evidence from assumptions copied between releases.',
    'An outsourced programmer can prepare scripts, fixtures, and rehearsal evidence, but production credentials and the final rollback decision should remain with the authorized company operator.',
    'Research takeaway: test rollback as a release capability and document irreversible boundaries before approval.'
  ], sources:[['DORA research program','https://dora.dev/research/'],['NIST Secure Software Development Framework','https://csrc.nist.gov/Projects/ssdf']] },
  { slug:'remote-programmer-documentation-coverage-research', title:'Documentation coverage for remote programming work', excerpt:'Research on measuring whether critical engineering tasks have usable, verified instructions.', topic:'Documentation coverage', published:'2026-08-12', body:[
    'Documentation coverage is not the percentage of code with comments. For distributed work, the stronger unit is a critical task or decision that another authorized person must be able to reproduce.',
    'Google technical-writing guidance emphasizes audience, scope, and usable instructions, while NIST SSDF highlights maintaining development and security information needed to support trustworthy software practices.',
    'Inventory recurring setup, test, release, recovery, access, and handoff tasks. For each task, record an owner, last verification date, prerequisites, safe examples, expected result, and escalation path.',
    'A document is covered only when a person other than its author can follow it in an approved environment and reach the expected result. Stale commands, hidden credentials, and undocumented assumptions should count as failed verification.',
    'Report coverage by task criticality and verification age. A small number of current recovery and release records can matter more than a large collection of untested notes.',
    'Research takeaway: measure verified operational knowledge, not document volume, and keep sensitive access outside public or broadly shared instructions.'
  ], sources:[['Google Technical Writing courses','https://developers.google.com/tech-writing'],['NIST Secure Software Development Framework','https://csrc.nist.gov/Projects/ssdf']] }
];
